class Solution {
public:
    long long countGood(std::vector<int>& nums, int k) {
        std::unordered_map<int, int> counts;
        long long pairs = 0, ans = 0;
        int left = 0, n = nums.size();
        for (int right = 0; right < n; ++right) {
            pairs += counts[nums[right]];
            counts[nums[right]]++;
            while (pairs >= k) {
                ans += (n - right);
                counts[nums[left]]--;
                pairs -= counts[nums[left]];
                left++;
            }
        }
        return ans;
    }
};

class Solution {
    public long countGood(int[] nums, int k) {
        java.util.Map<Integer, Integer> counts = new java.util.HashMap<>();
        long pairs = 0, ans = 0;
        int left = 0, n = nums.length;
        for (int right = 0; right < n; right++) {
            int x = nums[right];
            int c = counts.getOrDefault(x, 0);
            pairs += c;
            counts.put(x, c + 1);
            while (pairs >= k) {
                ans += (n - right);
                int lx = nums[left];
                int lc = counts.get(lx);
                counts.put(lx, lc - 1);
                pairs -= (lc - 1);
                left++;
            }
        }
        return ans;
    }
}

